// Sensor Ingestion Node
// Reads soil moisture, ambient temp, humidity, NPK, and weather API forecast
const simulator = global.get('simulator');
if (simulator) {
    msg.payload = simulator.getTelemetry();
} else {
    msg.payload = {
        soilMoisture: 32,
        soilTemp: 24.5,
        ambientTemp: 28.0,
        humidity: 68,
        npk: { nitrogen: 45, phosphorus: 30, potassium: 50 },
        weatherForecast: { rainProbability: 15, expectedRainfallMm: 0, hoursToRain: 12 },
        timestamp: new Date().toISOString()
    };
}
return msg;

// Perception Agent Node
// Analyzes raw telemetry into structured environmental risk signals
const t = msg.payload;

msg.perception = {
    moistureDeficit: t.soilMoisture < 35,
    severeDrought: t.soilMoisture < 25,
    highHeat: t.ambientTemp > 34,
    rainIncoming: t.weatherForecast.rainProbability >= 70 && t.weatherForecast.hoursToRain <= 3,
    pestThreat: t.humidity > 80 && t.ambientTemp > 24,
    npkDeficit: t.npk.nitrogen < 30 || t.npk.phosphorus < 20 || t.npk.potassium < 35
};

msg.telemetry = t;
return msg;

// Agentic AI Planner & Reasoning Engine
// Evaluates perceptions, invokes tools, resolves goal conflicts, forms multi-step action plan
const engine = global.get('agenticEngine');
const simulator = global.get('simulator');

let decision;
if (engine && msg.telemetry) {
    decision = engine.processCycle(msg.telemetry);
} else {
    decision = {
        primaryAction: 'IDLE',
        reasoningSteps: ['Default idle state'],
        actionPlan: ['Passive telemetry monitor']
    };
}

// Perform actuation on simulator if present
if (simulator && decision.primaryAction !== 'IDLE') {
    simulator.applyActuation(decision.primaryAction);
}

msg.payload = decision;
return msg;

// Log decision to memory context for long-term reflection
const history = global.get('agentMemory') || [];
history.unshift(msg.payload);
if (history.length > 50) history.pop();
global.set('agentMemory', history);
return msg;
